package com.pridesys.ticketing.repository; import com.pridesys.ticketing.dto.*; import com.pridesys.ticketing.entity.*; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class ProjectRecordRepository {private final ProjectRepository repo;private final ProjectMembershipRepository memberships;public ProjectRecordRepository(ProjectRepository r,ProjectMembershipRepository m){repo=r;memberships=m;}public List<ProjectRecord> findAll(){return repo.findAll().stream().map(this::record).toList();}public long create(UsersProjectsDtos.CreateProjectRequest r){return repo.save(new ProjectEntity(r.name().trim(),r.shortCode().trim().toUpperCase(),r.description())).getId();}public void update(long id,UsersProjectsDtos.UpdateProjectRequest r){var e=repo.findById(id).orElseThrow();e.setName(r.name().trim());e.setDescription(r.description());if(r.active()!=null)e.setActive(r.active());repo.save(e);}public boolean member(long p,long u){return repo.member(p,u);}public void addMember(long p,long u){memberships.save(new ProjectMembershipEntity(p,u));}public void removeMember(long p,long u){memberships.deleteById(new ProjectMembershipId(p,u));}public List<ProjectRecord> forUser(long u){return repo.forUser(u).stream().map(this::record).toList();}private ProjectRecord record(ProjectEntity e){return new ProjectRecord(e.getId(),e.getName(),e.getShortCode(),e.getDescription(),e.isActive());}}
